// Bounded ParGeo-style logarithmic batch-dynamic point forest; see package README/LICENSE.
#include <cstddef>
#include <cstdint>
#include <initializer_list>
struct BdkNode { int id,left,right; std::int64_t minx,maxx,miny,maxy; };
static bool bdk_less(int a,int b,int axis,const std::int64_t x[32],const std::int64_t y[32]){auto av=axis?y[a]:x[a],bv=axis?y[b]:x[b];if(av!=bv)return av<bv;auto aw=axis?x[a]:y[a],bw=axis?x[b]:y[b];return aw!=bw?aw<bw:a<b;}
static int bdk_build(int* ids,int lo,int hi,int depth,const std::int64_t x[32],const std::int64_t y[32],BdkNode nodes[32],int& used){if(lo>=hi)return -1;int axis=depth&1;for(int i=lo+1;i<hi;i++){int v=ids[i],j=i;while(j>lo&&bdk_less(v,ids[j-1],axis,x,y)){ids[j]=ids[j-1];--j;}ids[j]=v;}int mid=lo+(hi-lo)/2,at=used++;nodes[at].id=ids[mid];nodes[at].left=bdk_build(ids,lo,mid,depth+1,x,y,nodes,used);nodes[at].right=bdk_build(ids,mid+1,hi,depth+1,x,y,nodes,used);nodes[at].minx=nodes[at].maxx=x[ids[mid]];nodes[at].miny=nodes[at].maxy=y[ids[mid]];for(int child:{nodes[at].left,nodes[at].right})if(child>=0){auto c=nodes[child];if(c.minx<nodes[at].minx)nodes[at].minx=c.minx;if(c.maxx>nodes[at].maxx)nodes[at].maxx=c.maxx;if(c.miny<nodes[at].miny)nodes[at].miny=c.miny;if(c.maxy>nodes[at].maxy)nodes[at].maxy=c.maxy;}return at;}
static std::int64_t bdk_box(const BdkNode& n,std::int64_t qx,std::int64_t qy){auto dx=qx<n.minx?n.minx-qx:qx>n.maxx?qx-n.maxx:0;auto dy=qy<n.miny?n.miny-qy:qy>n.maxy?qy-n.maxy:0;return dx*dx+dy*dy;}
static void bdk_query(int at,const BdkNode nodes[32],const std::int64_t x[32],const std::int64_t y[32],const bool active[32],std::int64_t qx,std::int64_t qy,bool& found,int& best_id,std::int64_t& best){if(at<0||(found&&bdk_box(nodes[at],qx,qy)>best))return;auto n=nodes[at];int id=n.id;if(active[id]){auto dx=x[id]-qx,dy=y[id]-qy,d=dx*dx+dy*dy;if(!found||d<best||(d==best&&id<best_id)){found=true;best=d;best_id=id;}}int a=n.left,b=n.right;if(a>=0&&b>=0&&bdk_box(nodes[b],qx,qy)<bdk_box(nodes[a],qx,qy)){int t=a;a=b;b=t;}bdk_query(a,nodes,x,y,active,qx,qy,found,best_id,best);bdk_query(b,nodes,x,y,active,qx,qy,found,best_id,best);}
static void bdk_insert(int levels[6][32],int sizes[6],int id){int carry[32]={id};int count=1;for(int level=0;level<6;level++){if(sizes[level]==0){for(int i=0;i<count;i++)levels[level][i]=carry[i];sizes[level]=count;return;}int next[32],next_count=0;for(int i=0;i<sizes[level];i++)next[next_count++]=levels[level][i];for(int i=0;i<count;i++)next[next_count++]=carry[i];sizes[level]=0;for(int i=0;i<next_count;i++)carry[i]=next[i];count=next_count;}}
extern "C" std::int64_t batch_dynamic_kd_tree(const std::int64_t* input,std::size_t length,std::uint8_t* output,std::size_t capacity){
    if(input==nullptr||length<2||length>250)return -1;auto initial=input[0];if(initial<0||initial>8||length<2+3*static_cast<std::size_t>(initial))return -1;
    std::int64_t x[32]{},y[32]{},answers[8]{};bool ever[32]{},active[32]{};int levels[6][32]{},sizes[6]{};std::size_t pos=1;int inserted=0;
    for(int i=0;i<initial;i++){auto id=input[pos++],px=input[pos++],py=input[pos++];if(id<0||id>=32||ever[id]||px< -1000||px>1000||py< -1000||py>1000)return -1;for(int j=0;j<32;j++)if(active[j]&&x[j]==px&&y[j]==py)return -1;x[id]=px;y[id]=py;ever[id]=active[id]=true;inserted++;bdk_insert(levels,sizes,static_cast<int>(id));}
    if(pos>=length)return -1;auto batch_value=input[pos++];if(batch_value<1||batch_value>8)return -1;int batches=static_cast<int>(batch_value);
    for(int batch=0;batch<batches;batch++){if(pos+2>length)return -1;auto kind=input[pos++],count0=input[pos++];if((kind!=0&&kind!=1)||count0<1||count0>8)return -1;int count=static_cast<int>(count0);
        if(kind==0){if(inserted+count>32||pos+3*static_cast<std::size_t>(count)+2>length)return -1;std::size_t records_start=pos;
            for(int j=0;j<count;j++){auto id=input[pos++],px=input[pos++],py=input[pos++];if(id<0||id>=32||ever[id]||px< -1000||px>1000||py< -1000||py>1000)return -1;for(int t=0;t<32;t++)if(active[t]&&x[t]==px&&y[t]==py)return -1;for(int t=0;t<j;t++)if(input[records_start+3*t+1]==px&&input[records_start+3*t+2]==py)return -1;x[id]=px;y[id]=py;ever[id]=active[id]=true;inserted++;bdk_insert(levels,sizes,static_cast<int>(id));}
        }else{if(pos+static_cast<std::size_t>(count)+2>length)return -1;for(int j=0;j<count;j++){auto id=input[pos++];if(id<0||id>=32||!active[id])return -1;active[id]=false;}}
        auto qx=input[pos++],qy=input[pos++];if(qx< -1000||qx>1000||qy< -1000||qy>1000)return -1;bool found=false;std::int64_t best=0;int best_id=0;for(int level=0;level<6;level++)if(sizes[level]){int ids[32];for(int j=0;j<sizes[level];j++)ids[j]=levels[level][j];BdkNode nodes[32]{};int used=0;int root=bdk_build(ids,0,sizes[level],0,x,y,nodes,used);bdk_query(root,nodes,x,y,active,qx,qy,found,best_id,best);}if(!found)return -1;answers[batch]=best;
    }
    if(pos!=length)return -1;std::size_t needed=8*static_cast<std::size_t>(batches);if(output==nullptr||capacity<needed)return -2;for(std::size_t i=0;i<needed;i++)output[i]=static_cast<std::uint8_t>(static_cast<std::uint64_t>(answers[i/8])>>(8*(i%8)));return static_cast<std::int64_t>(needed);
}
